using FluentValidation;
namespace FintechApp.Requests.UpiBeneficiary { public class UpdateUpiBeneficiaryRequest { public int UpiBeneficiaryID { get; set; } public string Name { get; set; } = string.Empty; public string UpiID { get; set; } = string.Empty; public string GUID { get; set; } = string.Empty; public string SenderMobile { get; set; } = string.Empty; public string IPAddress { get; set; } = string.Empty; public int UpiSenderID { get; set; } public int UserID { get; set; } } public class UpdateUpiBeneficiaryRequestValidator : AbstractValidator<UpdateUpiBeneficiaryRequest> { public UpdateUpiBeneficiaryRequestValidator() { RuleFor(x => x.UpiBeneficiaryID).GreaterThan(0); } } }
